    wall=[[False]*W for _ in range(H)]
    dirs=[(0,1),(1,0),(1,1),(1,-1)]
    for p in sorted(twos):
        for q in sorted(twos):
            di,dj=q[0]-p[0],q[1]-p[1]
            g=gcd(abs(di),abs(dj))
            if g==0: continue
            di//=g; dj//=g
            r,c=p
            while True:
                r+=di;c+=dj
                if 0<=r<H and 0<=c<W and (r,c) in twos: break
                wall[r][c]=True
    # flood fill from outside through non-wall zeros (8-connectivity? try 4 first)
    seen=[[False]*W for _ in range(H)]
    dq=deque()
    for i in range(H):
        for j in (0,W-1):
            if not wall[i][j] and gi[i][j]==0 and not seen[i][j]:
                seen[i][j]=True; dq.append((i,j))
    for j in range(W):
        for i in (0,H-1):
            if not wall[i][j] and gi[i][j]==0 and not seen[i][j]:
                seen[i][j]=True; dq.append((i,j))
    while dq:
        r,c=dq.popleft()
        for dr in (-1,0,1):
            for dc in (-1,0,1):
