def rects_from_twos(twos):
    ts=sorted(twos)
    res=[]
    # try all pairs as opposite corners
    for (a,b),(c,d) in itertools.combinations(ts,2):
        rs=sorted({a,c}); cs=sorted({b,d})
        if len(rs)>=2 and len(cs)>=2:
            res.append((rs[0],rs[1],cs[0],cs[1]))
    return res
